def separate_paren_groups(paren_string: str) -> List[str]:
    """
    Separate top-level groups of balanced parentheses in a string.

    Parameters:
        paren_string: The input string containing multiple groups of nested parentheses.
                      Spaces in the string are ignored.

    Returns:
        A list of strings, each representing a balanced group from the input.
    """
    groups = []
    current = []
    depth = 0

    for ch in paren_string:
        if ch == ' ':
            continue
        if ch == '(':
            if depth == 0:
                current = ['(']
            else:
                current.append('(')
            depth += 1
        elif ch == ')':
            depth -= 1
            if depth < 0:
                raise ValueError("Unbalanced parentheses in input")
            current.append(')')
            if depth == 0:
                groups.append(''.join(current))
                current = []
        else:
            # ignore any non-parenthesis characters
            continue

    if depth != 0:
        raise ValueError("Unbalanced parentheses in input")

    return groups

