def max_product(num_str: str, N: int, K: int) -> int:
    """
    Returns the maximum product obtainable by inserting K multiplication signs
    into the string of digits num_str (of length N).
    """
    from functools import lru_cache

    @lru_cache(None)
    def dfs(start: int, cuts_left: int) -> int:
        # If no cuts left, multiply the remaining number
        if cuts_left == 0:
            return int(num_str[start:])

        best = 0
        # We need at least cuts_left digits after the current position to place the remaining cuts
        # The maximum end index we can consider is N - cuts_left
        max_end = N - cuts_left
        for end in range(start + 1, max_end + 1):
            left_part = int(num_str[start:end])
            right_product = dfs(end, cuts_left - 1)
            current_product = left_part * right_product
            if current_product > best:
                best = current_product
        return best

    # If K equals N-1, we multiply every individual digit
    if K == N - 1:
        product = 1
        for ch in num_str:
            product *= int(ch)
        return product

    return dfs(0, K)

